// OPTIMIZED IMAGE SPLITTER
// Handles multiple images per product with better validation

const FIELD_PREFIX = 'Image ';
const START_INDEX  = 1;
const MAX_IMAGES   = 23;
const DELETE_ORIGINAL_IMAGE_FIELDS = true;

const EXT_OK = /\.(jpe?g|png|webp|gif|avif|bmp|tiff)(\?.*)?$/i;
const BLOCK  = [/\/uploads\/anpc/i, /anpc-(sal|sol)\.png/i, /placeholder/i, /no-?image/i];

function collectAllImageUrls(input) {
  const out = [];
  const seen = new Set();

  const push = (u) => {
    if (!u) return;
    const s = String(u).trim().replace(/&amp;/g, '&');
    if (!/^https?:\/\//i.test(s)) return;
    if (!EXT_OK.test(s)) return;
    if (BLOCK.some((re) => re.test(s))) return;
    if (!seen.has(s)) { seen.add(s); out.push(s); }
  };

  const walk = (v) => {
    if (v == null) return;
    if (Array.isArray(v)) { v.forEach(walk); return; }
    if (typeof v === 'object') {
      if (v.src || v.url || v.href) push(v.src || v.url || v.href);
      Object.values(v).forEach(walk);
      return;
    }
    if (typeof v === 'string') {
      try { const parsed = JSON.parse(v); walk(parsed); return; } catch {}
      const rx = /(https?:\/\/[^\s"'<>]+?\.(?:jpe?g|png|webp|gif|avif|bmp|tiff)(?:\?[^\s"'<>]*)?)/ig;
      let m; while ((m = rx.exec(v))) push(m[1]);
      return;
    }
  };

  walk(input);
  return out;
}

return items.map(item => {
  const rec = { ...item.json };

  const sources = [
    rec['Image Src'], rec.images, rec.image, rec.photos, rec.photo, rec.gallery
  ];

  let urls = [];
  sources.forEach(s => { urls = urls.concat(collectAllImageUrls(s)); });
  urls = [...new Set(urls)].slice(0, MAX_IMAGES);

  urls.forEach((u, i) => {
    rec[`${FIELD_PREFIX}${START_INDEX + i}`] = u;
  });

  if (DELETE_ORIGINAL_IMAGE_FIELDS) {
    delete rec['Image Src'];
    delete rec.images;
    delete rec.image;
    delete rec.photos;
    delete rec.photo;
    delete rec.gallery;
  }

  return { json: rec };
});

