// OPTIMIZED UNIFIED FILTER
// Handles CREATE, UPDATE, and DEACTIVATE with improved SKU matching

const normalizeSKU = (raw) => {
  if (raw == null) return '';
  return String(raw)
    .normalize('NFKC')
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/\s+/g, '')
    .trim()
    .toUpperCase();
};

const gidNum = (gid) => String(gid || '').split('/').pop();

console.log("=== OPTIMIZED UNIFIED FILTER ===");

// 1) Build Shopify SKU index
const shopifyResults = $input.all().map(i => i.json);
const shopifySkuMap = new Map();
let totalShopifyVariants = 0;

for (const result of shopifyResults) {
  const productsData = result?.data?.products;
  if (!productsData) continue;

  const productEdges = productsData.edges ?? [];

  for (const productEdge of productEdges) {
    const product = productEdge.node;
    if (!product) continue;

    const productId = gidNum(product.id);
    const productTitle = product.title || '';
    const handle = product.handle || '';

    const variantEdges = product.variants?.edges ?? [];
    totalShopifyVariants += variantEdges.length;

    for (const variantEdge of variantEdges) {
      const variant = variantEdge.node;
      if (!variant) continue;

      const variantId = gidNum(variant.id);
      const skuRaw = variant.sku ? String(variant.sku).trim() : '';
      const skuKey = normalizeSKU(skuRaw);

      if (!skuKey || !variantId) continue;

      // Store only first occurrence
      if (!shopifySkuMap.has(skuKey)) {
        shopifySkuMap.set(skuKey, {
          product_id: productId,
          variant_id: variantId,
          handle,
          product_title: productTitle,
          variant_title: variant.title || 'Default Title',
          sku_raw: skuRaw,
          sku_key: skuKey,
          price: variant.price?.amount || variant.price || '',
          compare_at_price: variant.compareAtPrice?.amount || variant.compareAtPrice || '',
          inventory: variant.inventoryQuantity || 0
        });
      }
    }
  }
}

console.log(`Shopify: ${totalShopifyVariants} variants → ${shopifySkuMap.size} unique SKUs`);

// 2) Get and deduplicate incoming products
let incomingProductsRaw = [];
try {
  const splitImagesItems = $('Split Images').all();
  incomingProductsRaw = splitImagesItems.map(item => item.json);
} catch (error) {
  console.log(`Error accessing Split Images: ${error.message}`);
  return [{ json: { error: "Cannot access Split Images data" } }];
}

const incomingSkuMap = new Map();
const incomingSKUSet = new Set();
let duplicatesRemoved = 0;

for (const product of incomingProductsRaw) {
  const skuRaw = String(
    product['Variant SKU'] ||
    product.variant_sku ||
    product.sku ||
    product.SKU ||
    ''
  ).trim();

  const skuKey = normalizeSKU(skuRaw);

  if (!skuKey) {
    // Handle products without SKU separately
    const uniqueKey = `no_sku_${Math.random().toString(36).substr(2, 9)}`;
    incomingSkuMap.set(uniqueKey, {
      ...product,
      sku_raw: skuRaw,
      sku_key: '',
      no_sku: true
    });
    continue;
  }

  if (incomingSkuMap.has(skuKey)) {
    duplicatesRemoved++;
  } else {
    incomingSkuMap.set(skuKey, {
      ...product,
      sku_raw: skuRaw,
      sku_key: skuKey
    });
    incomingSKUSet.add(skuKey);
  }
}

console.log(`Incoming: ${incomingProductsRaw.length} raw → ${incomingSkuMap.size} unique (${duplicatesRemoved} duplicates removed)`);

// 3) Process CREATE and UPDATE actions
const results = [];
let createCount = 0;
let updateCount = 0;
let noSkuCount = 0;

for (const [key, product] of incomingSkuMap.entries()) {
  if (product.no_sku) {
    results.push({
      json: {
        ...product,
        action: 'create',
        no_sku_warning: true
      }
    });
    createCount++;
    noSkuCount++;
    continue;
  }

  const skuKey = product.sku_key;
  const match = shopifySkuMap.get(skuKey);

  if (match) {
    // UPDATE
    results.push({
      json: {
        ...product,
        action: 'update',
        shopify_product_id: match.product_id,
        shopify_variant_id: match.variant_id,
        shopify_handle: match.handle,
        existing_product_title: match.product_title,
        existing_variant_title: match.variant_title,
        existing_price: match.price,
        existing_compare_at_price: match.compare_at_price
      }
    });
    updateCount++;
  } else {
    // CREATE
    results.push({
      json: {
        ...product,
        action: 'create'
      }
    });
    createCount++;
  }
}

// 4) Process DEACTIVATE actions
let deactivateCount = 0;

for (const [skuKey, shopifyData] of shopifySkuMap.entries()) {
  if (!incomingSKUSet.has(skuKey)) {
    results.push({
      json: {
        action: 'deactivate',
        shopify_product_id: shopifyData.product_id,
        shopify_variant_id: shopifyData.variant_id,
        shopify_handle: shopifyData.handle,
        product_title: shopifyData.product_title,
        variant_title: shopifyData.variant_title,
        sku_raw: shopifyData.sku_raw,
        sku_key: shopifyData.sku_key,
        existing_price: shopifyData.price,
        existing_inventory: shopifyData.inventory,
        reason: 'SKU not found in source data'
      }
    });
    deactivateCount++;
  }
}

console.log(`\n=== RESULTS ===`);
console.log(`CREATE: ${createCount} (${noSkuCount} without SKU)`);
console.log(`UPDATE: ${updateCount}`);
console.log(`DEACTIVATE: ${deactivateCount}`);
console.log(`TOTAL: ${results.length}`);

return results;

// OPTIMIZED METAFIELD BUILDER
// Builds metafields and variant updates for newly created products

const S = v => (v == null ? '' : String(v).trim());
const money = v => {
  if (v == null || v === '') return null;
  const s = String(v).replace(/\s/g, '').replace(',', '.');
  const m = s.match(/-?\d+(\.\d+)?/);
  return m ? Number(m[0]).toFixed(2) : null;
};

const asListString = val => JSON.stringify([S(val)]);

const cleanList = raw => {
  const str = S(raw);
  return str.replace(/\s*\n+\s*/g, '\n').replace(/\s{2,}/g, ' ').replace(/,\s*,+/g, ', ');
};

const mapFuel = (raw) => {
  const v = (raw || '').toLowerCase().trim();
  const mapping = {
    'benzina': 'Benzină',
    'benzină': 'Benzină',
    'gasoline': 'Benzină',
    'petrol': 'Benzină',
    'diesel': 'Diesel',
    'hybrid': 'Hybrid',
    'phev': 'Plug-in Hybrid',
    'plug-in hybrid': 'Plug-in Hybrid',
    'electric': 'Electric',
    'ev': 'Electric',
    'lpg': 'LPG',
    'gpl': 'LPG'
  };
  return mapping[v] || 'Benzină';
};

const createdItems = $input.all();
const out = [];

console.log(`Processing ${createdItems.length} created products`);

// Get source data from Unified Filter
let sourceItems = [];
try {
  sourceItems = $('Unified Filter').all().map(i => i.json);
  console.log(`Found ${sourceItems.length} source items`);
} catch (e) {
  console.log(`Warning: Could not access Unified Filter data: ${e.message}`);
}

// Build SKU map for matching
const skuToSourceMap = new Map();
for (const item of sourceItems) {
  const sku = S(item['Variant SKU'] || item.variant_sku || item.sku || '');
  if (sku) {
    skuToSourceMap.set(sku, item);
  }
}

for (let i = 0; i < createdItems.length; i++) {
  const created = createdItems[i].json || {};
  const product_id = created.id;
  const variant_id = created?.variants?.[0]?.id;

  if (!product_id || !variant_id) {
    console.log(`ERROR: Missing product_id or variant_id for item ${i}`);
    continue;
  }

  const createdSku = S(created?.variants?.[0]?.sku || '');
  const row = skuToSourceMap.get(createdSku) || {};

  if (Object.keys(row).length === 0) {
    console.log(`Warning: No source data found for SKU "${createdSku}"`);
  }

  const variant_sku = S(row['Variant SKU'] || row.variant_sku || row.sku || createdSku || '');
  const variant_price = money(row['Variant Price'] || row.variant_price);

  // Build metafields blueprint
  let bp = {};
  if (Object.keys(row).length > 0) {
    bp = {
      sku: { type: 'single_line_text_field', value: variant_sku },
      price_gross: { type: 'number_decimal', value: money(row['Variant Price']) },
      pret_fara_tva: { type: 'number_decimal', value: money(row['Metafield: custom.pret_fara_tva [single_line_text_field]']) },
      currency: { type: 'single_line_text_field', value: 'RON' },
      nr_dos_: { type: 'single_line_text_field', value: S(row['Metafield: custom.nr_dos_ [single_line_text_field]']) },
      model: { type: 'single_line_text_field', value: S(row['Metafield: custom.model [single_line_text_field]']) },
      marca: { type: 'single_line_text_field', value: S(row['Metafield: custom.marca [single_line_text_field]']) },
      putere_kw: { type: 'single_line_text_field', value: S(row['Metafield: custom.putere_kw [single_line_text_field]']) },
      putere_cp: { type: 'single_line_text_field', value: S(row['Metafield: custom.putere_cp [single_line_text_field]']) },
      transmisie: { type: 'list.single_line_text_field', value: asListString(row['Metafield: custom.transmisie [list.single_line_text_field]'] || '') },
      tva: { type: 'single_line_text_field', value: S(row['Metafield: custom.tva [single_line_text_field]']) },
      cilindree: { type: 'single_line_text_field', value: S(row['Metafield: custom.cilindree [single_line_text_field]']) },
      cutie_viteze: { type: 'single_line_text_field', value: S(row['Metafield: custom.cutie_viteze [single_line_text_field]']) },
      culoare: { type: 'single_line_text_field', value: S(row['Metafield: custom.culoare [single_line_text_field]']) },
      kilometraj: { type: 'single_line_text_field', value: S(row['Metafield: custom.km [single_line_text_field]']) },
      data_livrarii: { type: 'single_line_text_field', value: S(row['Metafield: custom.data_livrarii [single_line_text_field]']) },
      body_type: { type: 'single_line_text_field', value: S(row['Metafield: custom.body_type [single_line_text_field]']) },
      fuel: { type: 'single_line_text_field', value: mapFuel(row['Metafield: custom.fuel [single_line_text_field]']) },
      dotari: { 
        type: 'multi_line_text_field',
        value: Array.isArray(row['Metafield: custom.dotari [multi_line_text_field]'])
          ? cleanList(row['Metafield: custom.dotari [multi_line_text_field]'].join(', '))
          : cleanList(row['Metafield: custom.dotari [multi_line_text_field]'] || '')
      }
    };
  }

  // Build metafields array
  const metafields = Object.entries(bp)
    .filter(([, def]) => def && def.value != null && def.value !== '')
    .map(([key, def]) => ({
      ownerId: `gid://shopify/Product/${product_id}`,
      namespace: 'custom',
      key,
      type: def.type,
      value: String(def.value)
    }));

  // Build variant update
  const variant_update = {};
  if (variant_sku || variant_price) {
    variant_update.variant = {
      id: variant_id,
      ...(variant_sku ? { sku: variant_sku } : {}),
      ...(variant_price ? { price: variant_price } : {})
    };
  }

  const graphql_body = metafields.length > 0 ? {
    query: `
      mutation metafieldsSet($metafields: [MetafieldsSetInput!]!) {
        metafieldsSet(metafields: $metafields) {
          metafields { key namespace value }
          userErrors { field message code }
        }
      }
    `.trim(),
    variables: { metafields }
  } : null;

  out.push({
    json: {
      product_id,
      variant_id,
      variant_update: Object.keys(variant_update).length > 0 ? variant_update : null,
      graphql_body,
      source_sku: variant_sku,
      has_metafields: metafields.length > 0
    }
  });
}

console.log(`Generated ${out.length} metafield updates`);
return out;

// OPTIMIZED PRICE UPDATER
// Compares prices and updates only when needed

const CONFIG = {
  PRICE_DIFF_EPS: 0.01,
  ALLOW_COMPARE_AT_PRICE: true
};

const toNum = (v) => {
  if (v == null) return NaN;
  const s = String(v).replace(/\s/g, '').replace(',', '.');
  const m = s.match(/-?\d+(?:\.\d+)?/);
  return m ? Number(m[0]) : NaN;
};

const to2 = (n) => Number.isFinite(n) ? n.toFixed(2) : null;

const items = $input.all();
const out = [];

let stats = {
  total: items.length,
  noPrice: 0,
  samePrice: 0,
  updated: 0,
  errors: 0
};

console.log(`Processing ${items.length} items for price updates`);

for (const item of items) {
  const data = item.json;

  const incomingPrice = toNum(data['Variant Price'] || data.variant_price || data.price);
  const existingPrice = toNum(data.existing_price);
  const existingCompareAt = toNum(data.existing_compare_at_price);

  if (!Number.isFinite(incomingPrice)) {
    stats.noPrice++;
    continue;
  }

  if (!Number.isFinite(existingPrice)) {
    // No existing price, always update
    const priceStr = to2(incomingPrice);

    out.push({
      json: {
        ...data,
        action: 'update_price',
        variant_gid: `gid://shopify/ProductVariant/${data.shopify_variant_id}`,
        incoming_price: priceStr,
        price_changed: true,
        graphql_body: {
          query: `mutation productVariantUpdate($input: ProductVariantInput!) {
            productVariantUpdate(input: $input) {
              productVariant { id price { amount currencyCode } }
              userErrors { field message }
            }
          }`,
          variables: {
            input: {
              id: `gid://shopify/ProductVariant/${data.shopify_variant_id}`,
              price: priceStr
            }
          }
        }
      }
    });
    stats.updated++;
    continue;
  }

  const priceDiff = Math.abs(incomingPrice - existingPrice);

  if (priceDiff <= CONFIG.PRICE_DIFF_EPS) {
    stats.samePrice++;
    continue;
  }

  // Price changed - prepare update
  const priceStr = to2(incomingPrice);
  const shouldSetCompareAt = CONFIG.ALLOW_COMPARE_AT_PRICE && 
                              !Number.isFinite(existingCompareAt) && 
                              existingPrice > incomingPrice;

  const compareAtStr = shouldSetCompareAt ? to2(existingPrice) : undefined;

  const input = {
    id: `gid://shopify/ProductVariant/${data.shopify_variant_id}`,
    price: priceStr
  };

  if (compareAtStr) {
    input.compareAtPrice = compareAtStr;
  }

  out.push({
    json: {
      ...data,
      action: 'update_price',
      variant_gid: `gid://shopify/ProductVariant/${data.shopify_variant_id}`,
      incoming_price: priceStr,
      old_price: to2(existingPrice),
      price_diff: to2(priceDiff),
      compare_at_price_set: compareAtStr || null,
      graphql_body: {
        query: `mutation productVariantUpdate($input: ProductVariantInput!) {
          productVariantUpdate(input: $input) {
            productVariant { id price { amount currencyCode } compareAtPrice { amount currencyCode } }
            userErrors { field message }
          }
        }`,
        variables: { input }
      }
    }
  });
  stats.updated++;
}

console.log(`\n=== PRICE UPDATE STATS ===`);
console.log(`Total: ${stats.total}`);
console.log(`No Price: ${stats.noPrice}`);
console.log(`Same Price: ${stats.samePrice}`);
console.log(`Updated: ${stats.updated}`);

return out;
